	// BW1W120 inlined BW1M119 0104caf0 (LHCombined Release)
	void SetParameters(float distance, float width)
	{
		Normal.Set(1.0f, 0.0f, 0.0f);
		Point.SetNull();
		Valid = false;
		Width = width;
		HalfWidth = width * 0.5f;
		Distance = distance;
