	// Static methods

	// BW1W120 inlined BW1M119 010a0050 (LHCombined Release)
	static void Reset()
	{
		int i;
		for (i = 0; i < FONT_CACHE_ENTRIES; i++)
		{
			cache[i].Code = 0;
		}
		for (i = 0; i < FONT_CACHE_PAGES; i++)
		{
			for (int j = 0; j < FONT_CACHE_LINES; j++)
			{
				page[i].Lines[j].Clear();
			}
		}
		memset(bits, 0, sizeof(bits));
		cachedamage = 0;
	}

