// Number of elements in a fixed-size array (MSVC 6.0 has no _countof)
#define ARRAY_SIZE(array) (sizeof(array) / sizeof((array)[0]))

// Limits value to the range [low, high]
// clang-format off
#define CLAMP(value, low, high) if (value < low) { value = low; } else if (value > high) { value = high; }
// clang-format on

inline void WrapScaled(float& value, float range, float inv_range)
{
	float t = value;
	value = t - (int)(t * inv_range) * range;
}

// Brings value back into the range [low, high] a period at a time
// clang-format off
#define WRAP(value, low, high, period) while (value < low) { value += period; } while (value > high) { value -= period; }
